-- 테스트(H2) 전용: Hibernate가 엔티티로 테이블을 만든 뒤 실행해요. schema.sql v0.3.2 모양을 맞춰요.
-- users는 auth(BE2) 소유라 엔티티가 없어서 필요한 컬럼만 만들어요.
CREATE TABLE IF NOT EXISTS users (user_id INT PRIMARY KEY, user_name VARCHAR(20) NOT NULL);
-- inspection_result는 ingest의 Inspection 엔티티가 아직 옛 이름(inspection)으로 매핑돼 있어서 직접 만들어요. ingest가 맞추면 이 줄은 건너뛰고 아래 ALTER만 적용돼요.
CREATE TABLE IF NOT EXISTS inspection_result (inspection_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, equipment_id VARCHAR(20) NOT NULL, product_id VARCHAR(30) NOT NULL, line_id VARCHAR(5) NOT NULL, paint_equipment_id VARCHAR(20), result VARCHAR(2) NOT NULL, inspected_at TIMESTAMP NOT NULL, shipped_at TIMESTAMP);
ALTER TABLE inspection_result ADD COLUMN IF NOT EXISTS paint_equipment_id VARCHAR(20);
